/// Creates a contract using the caller's client and signing configuration.
let bind (web3: Web3) (address: string) = web3.Eth.GetContract(abi, address)

/// Encodes approve(address,uint256) without RPC.
let encodeApprove (contract: Contract) (args: ApproveParams) =
    contract.GetFunctionBySignature("0x095ea7b3").GetData([| box args.To; box args.TokenId |])

let decodeApproveResult (data: string) : ApproveResult =
    Nethereum.ABI.FunctionEncoding.FunctionCallDecoder().DecodeFunctionOutput(Activator.CreateInstance<ApproveResult>(), data)

/// Sends through the client's configured transaction manager.
let sendApprove (contract: Contract) (options: TransactionInput) (args: ApproveParams) =
    if isNull options then nullArg "options"
    if not (isNull options.Value) && options.Value.Value <> BigInteger.Zero then invalidArg "options" "Function is not payable"
    options.To <- contract.Address
    contract.GetFunctionBySignature("0x095ea7b3").SendTransactionAsync(options, [| box args.To; box args.TokenId |])

